pub var g_sky_pipeline: ?*wgpu.RenderPipeline = null;
pub var g_sky_uniform_buffer: ?*wgpu.Buffer = null;
pub var g_sky_bind_group: ?*wgpu.BindGroup = null;
pub var g_sky_bind_group_layout: ?*wgpu.BindGroupLayout = null;
// 1×1 white default texture so every mesh has *something* to sample —
// multiplying by white collapses to the uniform color, preserving the
